insert into public.ecosystem_event_sources(event_id,url,source_type,supported_fields,finding_en,checked_at)
select e.id,s->>'url',s->>'source_type',array(select jsonb_array_elements_text(s->'supported_fields')),s->>'finding_en','2026-11-02'::date
from input join public.ecosystem_events e on e.slug=input.j->>'slug'
cross join lateral jsonb_array_elements(input.j->'sources') s
on conflict(event_id,url) do update set source_type=excluded.source_type,supported_fields=excluded.supported_fields,finding_en=excluded.finding_en,checked_at=excluded.checked_at;
