orizon_mode":"open_ended","latest_confirmed_event_end":"2029-09-13","confirmed_countries":["Austria","Belgium","Croatia","Czech Republic","Denmark","Finland","France","Germany","Greece","Italy","Norway","Poland","Portugal","Romania","Spain","Sweden","Switzerland","Turkey","Ukraine","United Kingdom"],"confirmed_country_count":20,"core_count":27,"adjacent_count":30,"additions_dated":8,"additions_watchlist":7,"source_observations":90}}$run$::jsonb)
